# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">KUR\'AN VE SÜNNETE BAĞLILIK HADİSLERİ</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">VEDA HUTBESİ VE SEKALEYN HADİSİ</text>\n  <text x="34" y="85" font-size="11.2" fill="#1e3a8a">• Emanet 1: Allah\'ın Kelamı olan Kur\'an-ı Kerim.</text>\n  <text x="34" y="110" font-size="11.2" fill="#1e3a8a">• Emanet 2: Hz. Peygamber\'in (sav) Sahih Sünneti.</text>\n  <text x="34" y="135" font-size="11.2" fill="#1e3a8a">• Mesaj: İkisine birlikte sarılan hidayet üzere kalır.</text>\n  <text x="34" y="160" font-size="11.2" fill="#1e3a8a">• İrbâd b. Sâriye Hadisi: Sünnete sarılın, bid\'atten kaçının.</text>\n  <text x="34" y="185" font-size="11.2" fill="#1e3a8a">• Ayet Dayanağı: \'Peygamber size ne verdiyse onu alın\' (Haşr, 7).</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">ERÎKE (KOLTUK) HADİSİ VE MESAJI</text>\n  <text x="370" y="85" font-size="11.2" fill="#78350f">• Ravi: Sahabi Mikdâm b. Ma\'dîkerib (ra).</text>\n  <text x="370" y="110" font-size="11.2" fill="#78350f">• Kavram: Erîke -&gt; Rahatlık ve kibir koltuğu.</text>\n  <text x="370" y="135" font-size="11.2" fill="#78350f">• Eleştirilen Tutum: \'Bize yalnız Kur\'an yeter\' iddiası.</text>\n  <text x="370" y="160" font-size="11.2" fill="#78350f">• Hakikat: \'Bana Kur\'an ve bir o kadarı (sünnet) verildi.\'</text>\n  <text x="370" y="185" font-size="11.2" fill="#78350f">• Hüküm: Resulullah\'ın haram kıldığı Allah\'ın haramı gibidir.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Kur\'an-ı Kerim\'i sahih sünnetten koparmak, vahyin pratik hayata uygulanış modelini ortadan kaldırmak demektir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">HADİS YORUMLAMA İLKELERİ VE SÜNNETİN ÜÇ TEMEL İŞLEVİ</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">HADİS YORUMLAMA USUL VE ÖLÇÜTLERİ</text>\n  <text x="34" y="85" font-size="11.2" fill="#14532d">• 1. Sahihlik Kontrolü: Sened ve metin sıhhatinin tespiti.</text>\n  <text x="34" y="110" font-size="11.2" fill="#14532d">• 2. Bütüncül Bakış: Kur\'an ve diğer hadislerle birlikte okuma.</text>\n  <text x="34" y="135" font-size="11.2" fill="#14532d">• 3. Bağlam Analizi: Sebeb-i vürûd, zaman, mekân ve muhatap.</text>\n  <text x="34" y="160" font-size="11.2" fill="#14532d">• 4. Dil ve Üslup: Hakikat, mecaz, temsil ve deyimlerin tespiti.</text>\n  <text x="34" y="185" font-size="11.2" fill="#14532d">• 5. Maksat (Gaye): Hükmün ardındaki ilahi hikmeti kavrama.</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">SÜNNETİN KUR\'AN KARŞISINDAKİ İŞLEVLERİ</text>\n  <text x="370" y="85" font-size="11.2" fill="#1e3a8a">• 1. Beyan (Tebyin): Mücmel ayetleri açıklama (Namaz, Hac).</text>\n  <text x="370" y="110" font-size="11.2" fill="#1e3a8a">• 2. Tekit (Teyit): Kur\'an hükümlerini destekleyip pekiştirme.</text>\n  <text x="370" y="135" font-size="11.2" fill="#1e3a8a">• 3. Teşri: Kur\'an\'da geçmeyen konularda hüküm koyma.</text>\n  <text x="370" y="160" font-size="11.2" fill="#1e3a8a">• • Beyan Örneği: \'Beni nasıl namaz kılıyor gördüyseniz...\'</text>\n  <text x="370" y="185" font-size="11.2" fill="#1e3a8a">• • Teşri Örneği: Yırtıcı hayvan etlerinin haram kılınması.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Nahl suresi 44. ayet: \'İnsanlara indirileni açıklayasın (li-tübeyyine) diye sana da Zikr\'i indirdik.\'</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">BİRİNCİ ÜNİTE SENTEZİ: HADİS İLMİNİN TEMEL KAVRAMLARI</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">HADİSİN YAPISI VE TÜRLERİ</text>\n  <text x="34" y="85" font-size="11.2" fill="#581c87">• Sened (İsnat): Hadisi aktaran raviler silsilesi (zinciri).</text>\n  <text x="34" y="110" font-size="11.2" fill="#581c87">• Metin: Senedin sonunda yer alan asıl hadis ifadeleri.</text>\n  <text x="34" y="135" font-size="11.2" fill="#581c87">• Ravi: Hadisi rivayet eden kişi | Muhaddis: Hadis âlimi.</text>\n  <text x="34" y="160" font-size="11.2" fill="#581c87">• Kavlî Sünnet: Sözler | Fiilî: Uygulamalar | Takrîrî: Onaylar.</text>\n  <text x="34" y="185" font-size="11.2" fill="#581c87">• Şemail: Fiziki ve ahlaki özellikler | Hilye: Şemail levhası.</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">KAYNAĞINA GÖRE HADİS ÇEŞİTLERİ</text>\n  <text x="370" y="85" font-size="11.2" fill="#7c2d12">• 1. Kudsî Hadis: Manası Allah\'a, lafzı Peygambere ait hadis.</text>\n  <text x="370" y="110" font-size="11.2" fill="#7c2d12">• 2. Merfû Hadis: Doğrudan Hz. Peygamber\'e (sav) ait hadis.</text>\n  <text x="370" y="135" font-size="11.2" fill="#7c2d12">• 3. Mevkuf Hadis: Sahabeye nispet edilen söz ve fiiller.</text>\n  <text x="370" y="160" font-size="11.2" fill="#7c2d12">• 4. Maktû Hadis: Tâbiîn âlimlerine nispet edilen sözler.</text>\n  <text x="370" y="185" font-size="11.2" fill="#7c2d12">• Dikkat: Kudsî hadis namazda Kur\'an yerine okunmaz.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">İsnat sistemi İslam medeniyetinin bilgiyi doğrulamak için geliştirdiği özgün bir bilimsel denetim yöntemidir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
